import {performance} from 'node:perf_hooks';
import {availableParallelism} from 'node:os';
const root=process.cwd(),own=relative(root,fileURLToPath(import.meta.url)),start=performance.now();
const TOTAL_BUDGET_MS=600000,TEST_BUDGET_MS=480000;
let deadline=start+TOTAL_BUDGET_MS;
const args=Object.fromEntries(process.argv.slice(2).map(s=>{const i=s.indexOf('=');return i<0?[s,true]:[s.slice(0,i),s.slice(i+1)];}));
const fail=m=>{throw new Error('RELEASE HOLD: '+m);};
const hash=(a,b)=>createHash(a).update(b).digest('hex');
function run(cmd,argv,{capture=false,label=cmd,budgetMs=90000}={}){
 const began=performance.now(),remaining=Math.floor(Math.min(deadline-began,budgetMs));if(remaining<=0)fail(`total gate budget exhausted before ${label}`);
 if(!capture)console.log(JSON.stringify({gatePhase:label,event:'start',budgetSeconds:remaining/1000,elapsedSeconds:(began-start)/1000}));
 const r=spawnSync(cmd,argv,{cwd:root,encoding:capture?'utf8':undefined,stdio:capture?'pipe':'inherit',env:Object.fromEntries(Object.entries(process.env).filter(([k])=>k!=='NODE_TEST_CONTEXT')),timeout:remaining,killSignal:'SIGKILL',detached:true,maxBuffer:32*1024*1024});
 if(r.pid){try{process.kill(-r.pid,'SIGKILL');}catch(e){if(e.code!=='ESRCH')throw e;}}
 const elapsed=((performance.now()-began)/1000).toFixed(2);
 if(r.error||r.status!==0){const why=r.error?.code==='ETIMEDOUT'?`TIMEOUT after ${elapsed}s (phase budget ${remaining/1000}s); no release performed; inspect last test and phase logs`:`exit ${r.error?.code||r.signal||r.status} after ${elapsed}s`;fail(`${label}: ${why}`);}
 if(!capture)console.log(JSON.stringify({gatePhase:label,event:'passed',elapsedSeconds:Number(elapsed)}));return r.stdout;
}
function snapshot(tree){
 const head=run('git',['rev-parse','HEAD^{tree}'],{capture:true}).trim();if(head!==tree)fail('HEAD tree is not the explicitly reviewed release');
 const raw=run('git',['ls-tree','-rz',tree],{capture:true}),expected=new Map();
 for(const record of raw.split('\0').filter(Boolean)){const m=/^(100644|100755) blob ([a-f0-9]{40})\t(.+)$/.exec(record);if(!m||m[3].split('/').some(p=>!p||p==='..'||p==='.'||['.git','node_modules','dist'].includes(p)))fail('unsupported source tree entry');expected.set(m[3],{mode:m[1],sha:m[2]});}
 const actual=[];function walk(dir=''){for(const entry of readdirSync(resolve(root,dir),{withFileTypes:true})){if(!dir&&['.git','node_modules','dist'].includes(entry.name))continue;const p=dir?dir+'/'+entry.name:entry.name;if(entry.isDirectory())walk(p);else{if(!entry.isFile())fail('source must be regular file: '+p);actual.push(p);}}}walk();
 if(actual.length!==expected.size||actual.some(p=>!expected.has(p)))fail('unknown or missing source files');
 for(const p of actual){const info=lstatSync(resolve(root,p));if(info.size>128*1024*1024)fail('oversized source: '+p);const bytes=readFileSync(resolve(root,p)),e=expected.get(p),blob=hash('sha1',Buffer.concat([Buffer.from(`blob ${bytes.length}\0`),bytes]));if(blob!==e.sha||((info.mode&0o111)?'100755':'100644')!==e.mode)fail('source bytes/mode changed: '+p);}
 return actual.sort();
}
try{
 if(Object.keys(args).some(k=>!['--gate-sha256','--expect-tree','--verify-only','--budget-ms'].includes(k)))fail('unknown gate argument');
 if(!/^[a-f0-9]{64}$/.test(args['--gate-sha256']||'')||hash('sha256',readFileSync(fileURLToPath(import.meta.url)))!==args['--gate-sha256'])fail('external gate SHA-256 pin missing or mismatched');
 if(!/^[a-f0-9]{40}$/.test(args['--expect-tree']||''))fail('explicit reviewed Git tree required');
 if(own!=='scripts/pinball-shadow-release-gate.mjs')fail('gate outside admitted location');
 if(args['--budget-ms']!==undefined){const n=Number(args['--budget-ms']);if(!Number.isInteger(n)||n<1||n>TOTAL_BUDGET_MS)fail('budget may only lower the fixed ceiling');deadline=start+n;}
 const files=snapshot(args['--expect-tree']);
 if(args['--verify-only']){console.log(JSON.stringify({verified:true,tree:args['--expect-tree'],files:files.length}));process.exit(0);}
 const patterns=[/^tests\/(punchline-portal-provenance|punchline-catalog|punchline-entry-count|fighter-entry-count|portal-catalog|portal-art|render|home-layout|home-views-api|home-views-client|hurdles-catalog|soul-catalog|platform-home-label)\.test\.mjs$/,/^tests\/pinball\/.*\.test\.mjs$/,/^tests\/pinball-.*\.test\.mjs$/,/^tests\/.*counts.*\.test\.mjs$/,/^tests\/leaderboard-.*\.test\.mjs$/,/^tests\/(provenance-session|narrow-hud-layout|word-lamp-visual|overtime-events|overtime-presentation|shadow-workers|shadow-worker-visual|boss-overtime-clock|preview-upload-isolation|catalog-release|fast-hands-cooldown-backend|preview-fast-gate-provenance|shadow-release-provenance)\.test\.mjs$/,/^tests\/fast-hands\/(duck.*|.*input.*|shuttle|records|replay|result-copy|leaderboard.*)\.test\.mjs$/];
 const tests=files.filter(p=>patterns.some(pattern=>pattern.test(p)));
 for(const required of ['tests/punchline-portal-provenance.test.mjs','tests/punchline-catalog.test.mjs','tests/punchline-entry-count.test.mjs','tests/fighter-entry-count.test.mjs','tests/portal-catalog.test.mjs','tests/portal-art.test.mjs','tests/render.test.mjs','tests/home-layout.test.mjs','tests/home-views-api.test.mjs','tests/home-views-client.test.mjs','tests/hurdles-catalog.test.mjs','tests/soul-catalog.test.mjs','tests/platform-home-label.test.mjs','tests/pinball-palette-provenance.test.mjs','tests/pinball/office-palette.test.mjs','tests/pinball/space-a.test.mjs','tests/pinball-presentation-provenance.test.mjs','tests/pinball/desktop-gameplay-framing.test.mjs','tests/pinball/audio-session.test.mjs','tests/pinball/mobile-focus.test.mjs','tests/pinball/company-sign-framing.test.mjs','tests/pinball-inner-rail-provenance.test.mjs','tests/pinball/inner-rail.test.mjs','tests/pinball/mobile-ui.test.mjs','tests/pinball/mobile-camera.test.mjs','tests/pinball/window-visibility.test.mjs','tests/provenance-session.test.mjs','tests/pinball-gate-performance-provenance.test.mjs','tests/pinball/render-budget.test.mjs','tests/pinball/lottery-label.test.mjs','tests/pinball/office-routes.test.mjs','tests/pinball/raffle-machine.test.mjs','tests/pinball/route-visual.test.mjs','tests/pinball/word-depth.test.mjs','tests/pinball-open-lanes-provenance.test.mjs','tests/pinball/open-lanes.test.mjs','tests/pinball/open-lanes-rules.test.mjs','tests/pinball/lottery-hud-css.test.mjs','tests/pinball/lottery-hud.test.mjs','tests/pinball/gate-hud.test.mjs','tests/pinball/launcher-rearm.test.mjs','tests/pinball/offer-station-visual.test.mjs','tests/pinball-lottery-provenance.test.mjs','tests/pinball/lr-offer.test.mjs','tests/pinball/lottery-integration.test.mjs','tests/pinball/lottery-events.test.mjs','tests/pinball/lottery-assists.test.mjs','tests/pinball/lottery-render.test.mjs','tests/pinball/lottery-position.test.mjs','tests/pinball-flow-provenance.test.mjs','tests/pinball-flow-scope.test.mjs','tests/pinball/flow-rules.test.mjs','tests/pinball/optional-interaction.test.mjs','tests/pinball/upper-assists.test.mjs','tests/pinball/interaction-offer-ui.test.mjs','tests/narrow-hud-layout.test.mjs','tests/pinball/word-lamps.test.mjs','tests/word-lamp-visual.test.mjs','tests/pinball/overtime-core.test.mjs','tests/pinball/interaction-clock.test.mjs','tests/overtime-events.test.mjs','tests/shadow-workers.test.mjs','tests/shadow-release-provenance.test.mjs'])if(!tests.includes(required))fail('required test absent: '+required);
 console.log(JSON.stringify({releaseTree:args['--expect-tree'],testFiles:tests.length,budgetSeconds:TOTAL_BUDGET_MS/1000,testBudgetSeconds:TEST_BUDGET_MS/1000,testConcurrency:2,availableParallelism:availableParallelism()}));
 run(process.execPath,['--test','--test-concurrency=2',...tests],{label:'complete impact tests',budgetMs:TEST_BUDGET_MS});snapshot(args['--expect-tree']);
 run('npm',['run','build'],{label:'static build'});run(process.execPath,['scripts/verify.mjs'],{label:'output references'});run('npm',['run','check:release','--','--expect=preview'],{label:'preview release preflight'});snapshot(args['--expect-tree']);
 console.log(JSON.stringify({releaseGate:'passed',tree:args['--expect-tree'],elapsedSeconds:(performance.now()-start)/1000}));
}catch(e){console.error(e.message);process.exitCode=1;}

import {withProvenanceSession,manifestText} from './provenance-session.mjs';
// Exact additive boundary for the approved PunchlinePortal import. Live behavior tests
// continue reading node:fs and runtime modules, never this historical view.
import {readFileSync as actual} from 'node:fs';
import {createHash} from 'node:crypto';
import {fileURLToPath} from 'node:url';
import {resolve,relative,sep,isAbsolute} from 'node:path';
import assert from 'node:assert/strict';
const root=fileURLToPath(new URL('../../',import.meta.url));
export const sha256=b=>createHash('sha256').update(b).digest('hex');
export const gitBlob=b=>createHash('sha1').update(`blob ${b.length}\0`).update(b).digest('hex');
const baselineBytes=actual(new URL('../../docs/punchline-portal/BASELINE.json',import.meta.url));
assert.equal(sha256(baselineBytes),'5092390eb3b0b88af2e27763c50f9530a7bea47dcc9246e098a1a5111a6625f9','immutable PunchlinePortal parent and admitted paths');
const freeze=value=>{if(value&&typeof value==='object'){Object.values(value).forEach(freeze);Object.freeze(value);}return value;};
export const baseline=freeze(JSON.parse(baselineBytes));
const previous=new Map(baseline.files.map(f=>[f.path,f.gitBlob]));
export function verifyBase(b){
 assert.equal(b.baseCommit,'66aba49d25ac447292faf784029cf4d809e8521b');assert.equal(b.baseTree,'eb4f92da75f858514ee89cbb071cd76715fd4462');assert.deepEqual(b,baseline);
 const tree={};for(const f of b.files){const parts=f.path.split('/');let d=tree;for(const name of parts.slice(0,-1))d=d[name]??={};assert.ok(!d[parts.at(-1)],'duplicate parent path');d[parts.at(-1)]={file:f};}
 function digest(d){const entries=Object.entries(d).sort(([a,x],[b,y])=>Buffer.compare(Buffer.from(a+(x.file?'':'/')),Buffer.from(b+(y.file?'':'/'))));const bytes=Buffer.concat(entries.map(([n,x])=>Buffer.concat([Buffer.from(`${x.file?x.file.mode:'40000'} ${n}\0`),Buffer.from(x.file?x.file.gitBlob:digest(x),'hex')])));return createHash('sha1').update(`tree ${bytes.length}\0`).update(bytes).digest('hex');}
 assert.equal(digest(tree),b.baseTree);return true;
}
verifyBase(baseline);
const manifestPath='docs/punchline-portal/MANIFEST.json';
let cachedText,cached;const validated=new WeakSet();
function uncached_manifest(){const url=new URL('../../'+manifestPath,import.meta.url),text=manifestText(url,()=>actual(url,'utf8'));if(text!==cachedText){const parsed=freeze(JSON.parse(text));cachedText=text;cached=parsed;}return cached;}
export function validate(m){
 if(m===cached&&validated.has(m))return m;
 assert.equal(m.baseCommit,baseline.baseCommit);assert.equal(m.baseTree,baseline.baseTree);
 assert.deepEqual(m.files.map(f=>f.path).sort(),baseline.modifiedPaths);
 assert.deepEqual([...m.addedPaths].sort(),baseline.addedPaths);
 assert.deepEqual(m.addedFiles.map(f=>f.path).sort(),baseline.addedPaths.filter(p=>p!==manifestPath));
 for(const f of m.files){assert.equal(typeof f.beforeText,'string');const b=Buffer.from(f.beforeText);assert.equal(f.beforeGitBlob,previous.get(f.path));assert.equal(gitBlob(b),f.beforeGitBlob);assert.equal(sha256(b),f.beforeSha256);assert.match(f.gitBlob,/^[a-f0-9]{40}$/);assert.match(f.sha256,/^[a-f0-9]{64}$/);}
 for(const f of m.addedFiles){assert.match(f.gitBlob,/^[a-f0-9]{40}$/);assert.match(f.sha256,/^[a-f0-9]{64}$/);}
 if(m===cached)validated.add(m);return m;
}
function uncached_punchlinePortalParentBytes(path,bytes,m=manifest()){
 validate(m);bytes=Buffer.from(bytes);const f=m.files.find(f=>f.path===path);if(!f)return bytes;
 const before=Buffer.from(f.beforeText);if(before.equals(bytes))return before;
 assert.equal(gitBlob(bytes),f.gitBlob,path+' punchlinePortal live drift');assert.equal(sha256(bytes),f.sha256,path+' punchlinePortal live SHA256 drift');return before;
}
function uncached_readBeforePunchlinePortal(file,options){
 const absolute=file instanceof URL?fileURLToPath(file):resolve(String(file)),path=relative(root,absolute).split(sep).join('/');
 if(!path||path==='..'||path.startsWith('../')||isAbsolute(path))return actual(file,options);
 const encoding=typeof options==='string'?options:options?.encoding;
 const bytes=actual(file,typeof options==='object'&&options?{...options,encoding:null}:undefined);
 const before=baseline.modifiedPaths.includes(path)?punchlinePortalParentBytes(path,bytes):bytes;return encoding?before.toString(encoding):before;
}
function uncached_inventoryBeforePunchlinePortal(paths,{read=p=>actual(new URL('../../'+p,import.meta.url)),runtimeOnly=false}={}){
 assert.equal(new Set(paths).size,paths.length,'duplicate punchlinePortal inventory');const m=validate(manifest());
 if(!paths.some(p=>m.addedPaths.includes(p)))return paths;
 const runtime=p=>/^(public|worker|src|config)\//.test(p),onlyRuntime=runtimeOnly||paths.every(runtime);
 const additions=m.addedPaths.filter(p=>!onlyRuntime||runtime(p));
 for(const p of additions)assert.equal(paths.filter(x=>x===p).length,1,p+' punchlinePortal addition must appear once');
 for(const f of [...m.files,...m.addedFiles].filter(f=>!onlyRuntime||runtime(f.path))){const bytes=read(f.path);assert.equal(gitBlob(bytes),f.gitBlob,f.path+' punchlinePortal inventory live drift');assert.equal(sha256(bytes),f.sha256,f.path+' punchlinePortal inventory SHA256 drift');}
 return paths.filter(p=>!additions.includes(p));
}
function uncached_assertCompleteInventory(paths,{read=p=>actual(new URL('../../'+p,import.meta.url))}={}){
 assert.deepEqual([...paths].sort(),[...baseline.files.map(f=>f.path),...baseline.addedPaths].sort(),'complete punchlinePortal inventory');
 assert.deepEqual(inventoryBeforePunchlinePortal(paths,{read}).sort(),baseline.files.map(f=>f.path).sort());
 for(const f of baseline.files)assert.equal(gitBlob(punchlinePortalParentBytes(f.path,read(f.path))),f.gitBlob,f.path+' exact immutable parent');
 return true;
}

export const manifest=(...args)=>withProvenanceSession(()=>uncached_manifest(...args));
export const punchlinePortalParentBytes=(...args)=>withProvenanceSession(()=>uncached_punchlinePortalParentBytes(...args));
export const readBeforePunchlinePortal=(...args)=>withProvenanceSession(()=>uncached_readBeforePunchlinePortal(...args));
export const inventoryBeforePunchlinePortal=(...args)=>withProvenanceSession(()=>uncached_inventoryBeforePunchlinePortal(...args));
export const assertCompleteInventory=(...args)=>withProvenanceSession(()=>uncached_assertCompleteInventory(...args));

import test from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync,readdirSync} from 'node:fs';
